-- Security layer of the database (hand written, not generated by Prisma).
--   1. Privileges of astax_app, the role used by API and worker.
--   2. updatedAt set by the database (ADR 0001).
--   3. Append-only audit log with a hash chain checked on insert (SIC-04).
--   4. Row level security: the second line of defence after the API (SIC-02).
--
-- Context variables, set with set_config(..., true) at the start of every
-- transaction by packages/db (withContext):
--   app.user_id          user acting
--   app.organization_id  organization of the active membership (X-AstAx-Context)
--   app.is_staff         'true' when the active membership belongs to AstAx
--   app.is_system        'true' for system jobs (worker, seed, outbox dispatcher)

-- ---------------------------------------------------------------------------
-- 1. Privileges
-- ---------------------------------------------------------------------------

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO astax_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO astax_app;
ALTER DEFAULT PRIVILEGES FOR ROLE astax_owner IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO astax_app;
ALTER DEFAULT PRIVILEGES FOR ROLE astax_owner IN SCHEMA public
  GRANT USAGE, SELECT ON SEQUENCES TO astax_app;

REVOKE ALL ON TABLE "_prisma_migrations" FROM astax_app;
-- History tables: rows are only ever added.
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE "AuditLog" FROM astax_app;
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE "Setting" FROM astax_app;
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE "LegalAcceptance" FROM astax_app;
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE "DomainEvent" FROM astax_app;

-- ---------------------------------------------------------------------------
-- Context helpers
-- ---------------------------------------------------------------------------

CREATE FUNCTION app_current_user_id() RETURNS uuid
  LANGUAGE sql STABLE AS
$$ SELECT nullif(current_setting('app.user_id', true), '')::uuid $$;

CREATE FUNCTION app_current_org_id() RETURNS uuid
  LANGUAGE sql STABLE AS
$$ SELECT nullif(current_setting('app.organization_id', true), '')::uuid $$;

CREATE FUNCTION app_is_system() RETURNS boolean
  LANGUAGE sql STABLE AS
$$ SELECT coalesce(current_setting('app.is_system', true), '') = 'true' $$;

CREATE FUNCTION app_is_privileged() RETURNS boolean
  LANGUAGE sql STABLE AS
$$ SELECT app_is_system() OR coalesce(current_setting('app.is_staff', true), '') = 'true' $$;

-- ---------------------------------------------------------------------------
-- 2. updatedAt
-- ---------------------------------------------------------------------------

CREATE FUNCTION set_updated_at() RETURNS trigger
  LANGUAGE plpgsql AS
$$ BEGIN NEW."updatedAt" := now(); RETURN NEW; END $$;

CREATE TRIGGER set_updated_at BEFORE UPDATE ON "User" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "Organization" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "Membership" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "TeamInvite" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "LegalDocument" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "LegalDocumentVersion" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "ListValue" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "Holiday" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "OutboxEvent" FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- 3. Audit log: append only, hash chain
-- ---------------------------------------------------------------------------

CREATE FUNCTION audit_log_reject_change() RETURNS trigger
  LANGUAGE plpgsql AS
$$ BEGIN
  RAISE EXCEPTION 'AuditLog is append-only (SIC-04)' USING ERRCODE = 'insufficient_privilege';
END $$;

CREATE TRIGGER audit_log_no_update_delete BEFORE UPDATE OR DELETE ON "AuditLog"
  FOR EACH ROW EXECUTE FUNCTION audit_log_reject_change();
CREATE TRIGGER audit_log_no_truncate BEFORE TRUNCATE ON "AuditLog"
  FOR EACH STATEMENT EXECUTE FUNCTION audit_log_reject_change();

-- Takes the chain lock for the rest of the transaction and returns the hash of
-- the last entry (the genesis hash when the log is empty). SECURITY DEFINER: the
-- caller may not see other organizations' rows, but must link to the true head.
CREATE FUNCTION audit_log_lock_head() RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS
$$ DECLARE head text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('astax.audit_log'));
  SELECT "hash" INTO head FROM "AuditLog" ORDER BY "seq" DESC LIMIT 1;
  RETURN coalesce(head, repeat('0', 64));
END $$;

REVOKE ALL ON FUNCTION audit_log_lock_head() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audit_log_lock_head() TO astax_app;

-- Safety net: an entry that does not link to the current head is refused,
-- so the chain can never fork.
CREATE FUNCTION audit_log_check_link() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS
$$ DECLARE head text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('astax.audit_log'));
  SELECT "hash" INTO head FROM "AuditLog" ORDER BY "seq" DESC LIMIT 1;
  IF NEW."prevHash" IS DISTINCT FROM coalesce(head, repeat('0', 64)) THEN
    RAISE EXCEPTION 'AuditLog entry does not link to the last entry (SIC-04)'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER audit_log_check_link BEFORE INSERT ON "AuditLog"
  FOR EACH ROW EXECUTE FUNCTION audit_log_check_link();

-- ---------------------------------------------------------------------------
-- 4. Row level security
-- ---------------------------------------------------------------------------

-- Organizations: own context, any organization the user belongs to (for the
-- context selector), everything for staff and system jobs.
ALTER TABLE "Organization" ENABLE ROW LEVEL SECURITY;
CREATE POLICY organization_select ON "Organization" FOR SELECT USING (
  app_is_privileged()
  OR "id" = app_current_org_id()
  OR EXISTS (
    SELECT 1 FROM "Membership" m
    WHERE m."organizationId" = "Organization"."id" AND m."userId" = app_current_user_id()
  )
);
CREATE POLICY organization_insert ON "Organization" FOR INSERT WITH CHECK (app_is_privileged());
CREATE POLICY organization_update ON "Organization" FOR UPDATE
  USING (app_is_privileged() OR "id" = app_current_org_id())
  WITH CHECK (app_is_privileged() OR "id" = app_current_org_id());
CREATE POLICY organization_delete ON "Organization" FOR DELETE USING (app_is_system());

-- Memberships: the active organization's, plus the user's own (context selector).
ALTER TABLE "Membership" ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_select ON "Membership" FOR SELECT USING (
  app_is_privileged()
  OR "organizationId" = app_current_org_id()
  OR "userId" = app_current_user_id()
);
CREATE POLICY membership_insert ON "Membership" FOR INSERT
  WITH CHECK (app_is_privileged() OR "organizationId" = app_current_org_id());
CREATE POLICY membership_update ON "Membership" FOR UPDATE
  USING (app_is_privileged() OR "organizationId" = app_current_org_id())
  WITH CHECK (app_is_privileged() OR "organizationId" = app_current_org_id());
CREATE POLICY membership_delete ON "Membership" FOR DELETE
  USING (app_is_privileged() OR "organizationId" = app_current_org_id());

ALTER TABLE "TeamInvite" ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_invite_all ON "TeamInvite" FOR ALL
  USING (app_is_privileged() OR "organizationId" = app_current_org_id())
  WITH CHECK (app_is_privileged() OR "organizationId" = app_current_org_id());

-- Users: oneself, colleagues of the active organization, everyone for staff.
ALTER TABLE "User" ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_select ON "User" FOR SELECT USING (
  app_is_privileged()
  OR "id" = app_current_user_id()
  OR EXISTS (
    SELECT 1 FROM "Membership" m
    WHERE m."userId" = "User"."id" AND m."organizationId" = app_current_org_id()
  )
);
CREATE POLICY user_insert ON "User" FOR INSERT WITH CHECK (app_is_privileged());
CREATE POLICY user_update ON "User" FOR UPDATE
  USING (app_is_privileged() OR "id" = app_current_user_id())
  WITH CHECK (app_is_privileged() OR "id" = app_current_user_id());
CREATE POLICY user_delete ON "User" FOR DELETE USING (app_is_system());

ALTER TABLE "LegalAcceptance" ENABLE ROW LEVEL SECURITY;
CREATE POLICY legal_acceptance_select ON "LegalAcceptance" FOR SELECT
  USING (app_is_privileged() OR "userId" = app_current_user_id());
CREATE POLICY legal_acceptance_insert ON "LegalAcceptance" FOR INSERT
  WITH CHECK (app_is_privileged() OR "userId" = app_current_user_id());

-- Audit log: anyone may append; reading is limited to the active organization's
-- own actions (VIS-08, further restricted by the API) and to staff.
ALTER TABLE "AuditLog" ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_log_insert ON "AuditLog" FOR INSERT WITH CHECK (true);
CREATE POLICY audit_log_select ON "AuditLog" FOR SELECT
  USING (app_is_privileged() OR "actorOrganizationId" = app_current_org_id());

-- Domain events and outbox: written by every use case, read by staff and jobs.
ALTER TABLE "DomainEvent" ENABLE ROW LEVEL SECURITY;
CREATE POLICY domain_event_insert ON "DomainEvent" FOR INSERT WITH CHECK (true);
CREATE POLICY domain_event_select ON "DomainEvent" FOR SELECT USING (app_is_privileged());

ALTER TABLE "OutboxEvent" ENABLE ROW LEVEL SECURITY;
CREATE POLICY outbox_insert ON "OutboxEvent" FOR INSERT WITH CHECK (true);
CREATE POLICY outbox_system ON "OutboxEvent" FOR ALL
  USING (app_is_system()) WITH CHECK (app_is_system());

-- Global reference data: readable by everyone, changed by staff and jobs only.
ALTER TABLE "Setting" ENABLE ROW LEVEL SECURITY;
CREATE POLICY setting_select ON "Setting" FOR SELECT USING (true);
CREATE POLICY setting_insert ON "Setting" FOR INSERT WITH CHECK (app_is_privileged());

ALTER TABLE "ListValue" ENABLE ROW LEVEL SECURITY;
CREATE POLICY list_value_select ON "ListValue" FOR SELECT USING (true);
CREATE POLICY list_value_write ON "ListValue" FOR ALL
  USING (app_is_privileged()) WITH CHECK (app_is_privileged());

ALTER TABLE "Holiday" ENABLE ROW LEVEL SECURITY;
CREATE POLICY holiday_select ON "Holiday" FOR SELECT USING (true);
CREATE POLICY holiday_write ON "Holiday" FOR ALL
  USING (app_is_privileged()) WITH CHECK (app_is_privileged());

ALTER TABLE "LegalDocument" ENABLE ROW LEVEL SECURITY;
CREATE POLICY legal_document_select ON "LegalDocument" FOR SELECT USING (true);
CREATE POLICY legal_document_write ON "LegalDocument" FOR ALL
  USING (app_is_privileged()) WITH CHECK (app_is_privileged());

ALTER TABLE "LegalDocumentVersion" ENABLE ROW LEVEL SECURITY;
CREATE POLICY legal_document_version_select ON "LegalDocumentVersion" FOR SELECT USING (true);
CREATE POLICY legal_document_version_write ON "LegalDocumentVersion" FOR ALL
  USING (app_is_privileged()) WITH CHECK (app_is_privileged());
